- = Alif, Lam, Mim. 2:1; 3:1; 29:1; 30:1; 31:1; 32:1
- = Bango nde bazali na nzela ya sembene oyo ewuti epai ya Nkolo wa bango, mpe bango nde bazali balongi. 2:5; 31:5
- = Oh bana ya Isalaele! Bokanisa bolamu na Ngai oyo Nagamisaki bino, mpe ete Nagotiyaki bino likolo ya mikili (bato) nyonso. 2:47; 2:122
- = Wana ezalaki ekolo oyo eleki. Ekoki na maye ekosaki, mpe bino bokoki na maye bokosaki. Mpe bokobongisama te тропа maye bazalaki kosala. 2:134; 2:141
- = Bakovanda na yango libela. Etumbu ekoleisama te mpo na bango, mpe bakozelama te. 2:162; 3:88
- = Longola baye bakobongola mitema na bango nsima na yango mpe bakomibongisa. Ya sólo, Allah azali Molimbisi, Mawa na Ye. 3:89; 24:5
- = Kasi baye bapengwi mpe baboyaki kondimisa bilembo na biso – bango nde bato ya lifelo. 5:10; 5:86
- = Mpe bilembo nyonso oyo ewuti epai ya Nkolo wa bango ekomelaka bango te, kasi bango babalukaka na yango. 6:4; 36:46
- = Mpe ya sólo, batiolaki batindami liboso na yo, kasi baye batiolaki bango, bakangamaki na oyo batiolaki. 6:10; 21:41
- = Loba: "Ya sólo, nazali kobanga, soki natosi Nkolo wa ngai te, etumbu ya mokolo monene." 6:15; 39:13
- = Na yango, mobembo ebeta bango, mpe bakufaki zingazinga na bandako na bango. 7:78; 7:91
- = Na yango, abwakaki lingenda na ye, mpe tala, ekómaki nyoka oyo emonanaka polele. 7:107; 26:32
- = Mpe abimisaki loboko na ye, mpe tala, ekómaki pembe (eyebana) mpo na baye bazali kotala. 7:108; 26:33
- = Balobaki: "Tondimaki na Nkolo wa mikili." 7:121; 26:47
- = Nkolo wa Mûsá na Hârûna. 7:122; 26:48
- = Mpe nakopekisa bango. Ya sólo, likita na ngai ezali makasi. 7:183; 68:45
- = Ye nde atindaki motindami na Ye na bokambi mpe na lingomba ya solo, mpo ete amatisa yango likolo ya lingomba nyonso, ata soki basangisi bakufi na yango. 9:33; 61:9
- = Oh Nkoma! Bundisa bapengwi mpe bampaka- mwinda, mpe kala makasi na bango. Mpe esika na bango ezali lifelo, mpe ezali esika ya mabe! 9:73; 66:9
- = Mpe bazali koloba: "Elaka oyo ekokoma tango nini, soki bozali bato ya solo?" 10:48; 21:38; 27:71; 34:29; 36:48; 67:25
- = Mpe ya sólo, totindaki Mûsá na bilembo na biso mpe na bokonzi oyo emonanaka polele. 11:96; 40:23
- = Mpe ya sólo, topesaki Mûsá buku, kani bakabwanaki тропа yango. Mpe soki ezalaki te na liloba oyo ebandaki epai ya Nkolo na yo, mbulamatari ekokaki kati na bango. Mpe ya sólo, bango bazali na ntembe тропа yango. 11:110; 41:45
- = Wana ezali pasi te mpo na Allah. 14:20; 35:17
- = "Mpe tango nakokokisa ye mpe nakopupela ye molimo na Ngai, na yango bokwea mpo na ye." 15:29; 38:72
- = Na yango, ba anzelu nyonso bakweaki. 15:30; 38:73
- = (Allah) alobaki: "Na yango, bimaka na yango, mpo ya sólo, ozali mobenganami." 15:34; 38:77
- = (Iblisi) alobaki: "Nkolo wa ngai! Na yango, pesa ngai mokano kino mokolo oyo bakosekwisama." 15:36; 38:79
- = (Allah) alobaki: "Na yango, ya sólo, ozali oyo bakopesa bango mokano." 15:37; 38:80
- = Kino mokolo ya tango oyo eyebani." 15:38; 38:81
- = Longola batumboli na Yo baye oponami kati na bango. 15:40; 38:83
- = Ya sólo, bakufi na motema bakozala na bilanga mpe na biloko. 15:45; 51:15
- = (Ibrahim) alobaki: "Na yango, likambo na bino ezali nini, oh batindami?" 15:57; 51:31
- = Balobaki: "Ya sólo, totindami epai ya bato ya masumu." 15:58; 51:32
- = Baye bandimaki mpe basangisaki kondima na bango na sembene te – bango bakozala na kimia, mpe bango nde bakambami. 16:42; 29:59
- = Mpo ete bapengwa na oyo topesaki bango. Bosepela, mpe bokoyeba. 16:55; 30:34
- = Na nsima, alandaki nzela. 18:89; 18:92
- = Kende epai ya Faraon. Ya sólo, ye aleki ndelo. 20:24; 79:17
- = Mpe baye babatelaka nzoto na bango. 23:5; 70:29
- = Longola epai ya basi na bango to oyo maboko na bango ya mobali ezali na yango – mpo ya sólo, bango bakosembwana te. 23:6; 70:30
- = Kasi oyo akoluka likolo ya yango, bango nde bakoleka ndelo. 23:7; 70:31
- = Mpe baye babatelaka malakisi na bango mpe mikakatano na bango. 23:8; 70:32
- = (Nuh) alobaki: "Nkolo wa ngai, tija ngai makasi, mpo bango baboyi kondima ngai." 23:26; 23:39
- = Ta, Sin, Mim. 26:1; 28:1
- = Oyo ezali mikapo ya buku oyo emonanaka polele. 26:2; 28:2
- = Ya sólo, kati na yango ezali elembo, kasi mingi na bango bandimaki te. 26:8; 26:67; 26:103; 26:121; 26:174; 26:190
- = Mpe ya sólo, Nkolo na yo – Ye ike Nguya-makasi, Mawa-mpenza. 26:9; 26:68; 26:104; 26:122; 26:140; 26:159; 26:175; 26:191
- = Mpe tokweyisaki bato mosusu. 26:66; 37:82
- = Ya sólo, ngai nazali motindami ya sembene mpo na bino. 26:107; 26:125; 26:143; 26:162; 26:178
- = Na yango, bobanga Allah mpe botosa ngai. 26:108; 26:110; 26:126; 26:131; 26:144; 26:150; 26:163; 26:179
- = Mpe ngai nazali kosenga bino lifuta te mpo na yango. Lifuta na ngai ezali epai ya Nkolo wa mikili. 26:109; 26:127; 26:145; 26:164; 26:180
- = Na bilanga mpe na biloko. 26:147; 44:52
- = Balobaki: "Ozali kati na baye babebisami na losambo." 26:153; 26:185
- = Longola mwasi na ye – tokanisaki ete ye azala kati na baye basali. 26:171; 37:135
- = Na nsima, tobebisaki bato mosusu. 26:172; 37:136
- = Mpe tonyeselaki bango mbula (ya mabanga), mpe ezalaki mbula mabe mpo na baye bakebisami! 26:173; 27:58
- = Boye bazali kosenga etumbu etyela? 26:204; 37:176
- = Baye basambelaka mpe bapesaka zakat, mpe bango bazali na kondima ya solo тропа mokolo ya suka. 27:3; 31:4
- = Mpe (kanisa, oh Muhammad) mokolo oyo akobelela bango mpe aloba: "Bazali wapi 'basangani' na ngai oyo bozalaki koloba?" 28:62; 28:74
- = Mpe bankoko na biso ya kala? 37:17; 56:48
- = Mpe bakopusana moko na mosusu, bazali komituna. 37:27; 52:25
- = Kasi (bango) batumboli ya Allah oyo baponami. 37:40; 37:74; 37:128; 37:160
- = Na bilanga ya esengo. 37:43; 56:12
- = Mpe totikaki mpo na ye (kombo ya malamu) kati na basi: 37:78; 37:108; 37:129
- = Ya sólo, lolenge wana nde tofutaka basali ya malamu. 37:80; 37:121; 37:131; 77:44
- = Ya sólo, ye azalaki kati na batumboli na biso bandimi. 37:81; 37:111; 37:132
- = Nini ezali na bino? Ndenge nini bokosambisa? 37:154; 68:36
- = (Kurani) ezali sé bokundoli mpo na mikili. 38:87; 81:27
- = Bokiti ya buku ewuti epai ya Allah, Nguya-makasi, Motema- mayele. 39:1; 45:2; 46:2
- = Ha, Mim. 40:1; 41:1; 42:1; 43:1; 44:1; 45:1; 46:1
- = Na buku oyo emonanaka polele. 43:2; 44:2
- = Na yango, tiká bango bazala na magesi mpe na lisano, kino bakokutana na mokolo na bango oyo bakanisami. 43:83; 70:42
- = (Bakoloba na bango): "Bolia mpe bomela na esengo mpo na oyo bozalaki kosala." 52:19; 77:43
- = To ozali kosenga bango lifuta, mpo bakolembisama na nyongo? 52:40; 68:46
- = To bazali na boyebi ya oyo ezipama, mpo bakokoma yango? 52:41; 68:47
- = Mpe ndenge nini etumbu na ngai mpe makebisi na ngai ezalaki! 54:16; 54:21; 54:30
- = Mpe ya sólo, tokokisaki Kurani mpo na bokundoli. Boye ezali moto oyo akokanisa? 54:17; 54:22; 54:32; 54:40
- = Mpe wapi bolamu ya Nkolo na bino oyo bokoboya kondima? 55:13; 55:16; 55:18; 55:21; 55:23; 55:25; 55:28; 55:30; 55:32; 55:34; 55:36; 55:38; 55:40; 55:42; 55:45; 55:47; 55:49; 55:51; 55:53; 55:55; 55:57; 55:59; 55:61; 55:63; 55:65; 55:67; 55:69; 55:71; 55:73; 55:75; 55:77
- = Lingomba lya bato ya kala. 56:13; 56:39
- = Mpe tokangamaki? 56:67; 68:27
- = Na yango, banzola nkombo ya Nkolo na yo, Monene-mpenza. 56:74; 56:96; 69:52
- = (Kurani) ezali bokiti ewuti epai ya Nkolo wa mikili. 56:80; 69:43
- = Maye mazali na likolo mpe maye mazali na nsé, nyonso bazali kokumisa Allah, mpe Ye ike Nguya-makasi, Motema- mayele. 59:1; 61:1
- = Ntango mikapo na biso ezali kotangema mpo na ye, alobi: "Masiso ya kala!" 68:15; 83:13
- = Na yango, akozala na bomoi ya esengo. 69:21; 101:7
- = Na bilanga ya likolo. 69:22; 88:10
- = Mpe akosindika te bato bapésa mabele na bato ya bobola. 69:34; 107:3
- = (Ete) ya sólo, oyo (Kurani) ezali liloba ya motindami ya lokumu. 69:40; 81:19
- = Ya sólo, oyo ezali bokundoli. Mpe oyo alingi, azwa nzela epai ya Nkolo wa ye. 73:19; 76:29
- = Na yango, oyo alingi, akanisa yango. 74:55; 80:12
- = Mawa na mokolo wana mpo na baboyi kondima! 77:15; 77:19; 77:24; 77:28; 77:34; 77:37; 77:40; 77:45; 77:47; 77:49; 83:10
- = Ya sólo, basaleli ya malamu bakozala na esengo. 82:13; 83:22
- = Ezali buku oyo ekomami. 83:9; 83:20
- = Na bibumbu ya lokumu, bazali kotala. 83:23; 83:35
- = Mpe bongoki Nkolo wa yango, mpe esengeli. 84:2; 84:5
- = Mpe ngai nazali te mosambeli ya oyo bozali kosambela. 109:3; 109:5
