- Ya soló, Nkolo na ye azali koyeba malamu oyo abungui na nzela na ye, mpe ye azali koyeba malamu baye bazali kokota (na nzela ya botamboli). (إِنَّ رَبَّكَ هُوَ أَعْلَمُ مَن يَضِلُّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ بِالْمُهْتَدِينَ) 6:117; 16:125; 68:7
- Ye oyo akelaki likolo na mabele na mikolo motoba, sima atii kiti na ye ya bokonzi. (الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَى عَلَى الْعَرْشِ) 7:54; 10:3; 57:4
- Mpe nani azali moto ya mabe koleka oyo akosala lokuta na Allah to akopengwa na bilembo na ye? (وَمَنْ أَظْلَمُ مِمَّنِ افْتَرَى عَلَى اللَّهِ كَذِبًا أَوْ كَذَّبَ بِآيَاتِهِ) 6:21; 7:37; 10:17
- Ye nde atindaki motindami na ye na bokambi mpe na lingomba ya solo, mpo akumisa yango likolo na mangomba manso. (هُوَ الَّذِي أَرْسَلَ رَسُولَهُ بِالْهُدَى وَدِينِ الْحَقِّ لِيُظْهِرَهُ عَلَى الدِّينِ كُلِّهِ) 9:33; 48:28; 61:9
- Ya soló, baye balobaki 'Allah azali Masiya, mwana ya Mariam' bapengwi. Loba... (لَّقَدْ كَفَرَ الَّذِينَ قَالُوا إِنَّ اللَّهَ هُوَ الْمَسِيحُ ابْنُ مَرْيَمَ قُلْ) 5:17; 5:72
- Okoki koyokisa bafufu na nzela ya libungi na bango te. Okoki koyokisa sé oyo andimi na bilembo na biso; mpe bango nde bato ya kotosa. (الْعُمْيِ عَن ضَلَالَتِهِمْ إِن تُسْمِعُ إِلَّا مَن يُؤْمِنُ بِآيَاتِنَا فَهُم مُّسْلِمُونَ) 27:81; 30:53
- Ndakisa ya bomoi ya mokili ezali lokola mai oyo tokitisaki kowuta na likolo, mpe na yango bilanga ya mabele esanganaki... (مَثَلُ الْحَيَاةِ الدُّنْيَا كَمَاءٍ أَنزَلْنَاهُ مِنَ السَّمَاءِ فَاخْتَلَطَ بِهِ نَبَاتُ الْأَرْضِ) 10:24; 18:45
- Kotisa kati na yango (masuwa) ya nyonso ndambo mibale, mpe libota na yo, longola sé oyo likambo ezalaki liboso kati na ye... (فِيهَا مِن كُلٍّ زَوْجَيْنِ اثْنَيْنِ وَأَهْلَكَ إِلَّا مَن سَبَقَ عَلَيْهِ الْقَوْلُ) 11:40; 23:27
- Nazali koloba na bino te ete bazulu ya Allah ezali epai na ngai, mpe nayebi mabombami te, mpe nazali koloba te... (لَّا أَقُولُ لَكُمْ عِندِي خَزَائِنُ اللَّهِ وَلَا أَعْلَمُ الْغَيْبَ وَلَا أَقُولُ) 6:50; 11:31
- Ya soló, Allah azali na boboto na bato, kasi ebele ya bato bazali kopesa matondi te. (إِنَّ اللَّهَ لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يَشْكُرُونَ) 2:243; 40:61
- Mpe elembo moko te na kati ya bilembo ya Nkolo na bango ekomelaki bango kasi bavundaki yango. (وَمَا تَأْتِيهِم مِّنْ آيَةٍ مِّنْ آيَاتِ رَبِّهِمْ إِلَّا كَانُوا عَنْهَا مُعْرِضِينَ) 6:4; 36:46
- Mpe bobanga mokolo oyo molimo moko ekosikola mosusu te, mpe ekokambama te kowuta na yango. (وَاتَّقُوا يَوْمًا لَّا تَجْزِي نَفْسٌ عَن نَّفْسٍ شَيْئًا وَلَا يُقْبَلُ مِنْهَا) 2:48; 2:123
- Ya soló, okoki koyokisa bakufi te, mpe okoki koyokisa bakufi matoyi tango bazali komima na mikongo. (إِنَّكَ لَا تُسْمِعُ الْمَوْتَى وَلَا تُسْمِعُ الصُّمَّ الدُّعَاءَ إِذَا وَلَّوْا مُدْبِرِينَ) 27:80; 30:52
- Epekisameli bino (kolya) nyama oyo ekufi, makila, nyama ya ngulu, mpe maye babomeli yango na kombo mosusu kasi ya Allah te. (حُرِّمَتْ عَلَيْكُمُ الْمَيْتَةُ وَالدَّمُ وَلَحْمُ الْخِنزِيرِ وَمَا أُهِلَّ لِغَيْرِ اللَّهِ بِهِ) 5:3; 16:115
- Maye manso mazali na likolo na mabele mazali kokumisa Allah. Mpe ye azali na bokasi, azali na bwanya. (سَبَّحَ لِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَهُوَ الْعَزِيزُ الْحَكِيمُ) 59:1; 61:1
- Longola sé baye bapetolimaki sima na yango mpe basali malamu. Ya soló, Allah azali molimbisi, azali na ngolu. (إِلَّا الَّذِينَ تَابُوا مِن بَعْدِ ذَلِكَ وَأَصْلَحُوا فَإِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ) 3:89; 24:5
- Baponaki na Nkolo na bango; tososola kati na bango moto moko te, mpe biso tokotosa ye. (النَّبِيُّونَ مِن رَّبِّهِمْ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّنْهُمْ وَنَحْنُ لَهُ مُسْلِمُونَ) 2:136; 3:84
- Kowuta na Nkolo na yo mpo okebisa bato oyo, ata moto moko te akebisaki bango liboso na yo, mpo bakoka... (مِّن رَّبِّكَ لِتُنذِرَ قَوْمًا مَّا أَتَاهُم مِّن نَّذِيرٍ مِّن قَبْلِكَ لَعَلَّهُمْ) 28:46; 32:3
- Eh Nkoma, bundisa bapengwi na bato ya kontana, mpe koma makasi na bango. Libanda na bango ezali lifelo! Mpe esika mabe ya kolandela! (يَا أَيُّهَا النَّبِيُّ جَاهِدِ الْكُفَّارَ وَالْمُنَافِقِينَ وَاغْلُظْ عَلَيْهِمْ وَمَأْوَاهُمْ جَهَنَّمُ وَبِئْسَ الْمَصِيرُ) 9:73; 66:9
- Ya soló, Nkolo na yo akosala kokata kati na bango na mokolo ya suka na maye bazalaki kokesana. (إِنَّ رَبَّكَ يَقْضِي بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ) 10:93; 45:17
- Alobaki: 'Nkolo na ngai, pesa ngai elembo.' Alobaki: 'Elembo na yo ete oloba na bato te.' (قَالَ رَبِّ اجْعَل لِّي آيَةً قَالَ آيَتُكَ أَلَّا تُكَلِّمَ النَّاسَ) 3:41; 19:10
- Bongo balola elongi na yo epai ya Masjid al-Haram. Mpe bisika nyonso oyo bokozala, bobalola elongi na bino epai na yango. (فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ وَحَيْثُ مَا كُنتُمْ فَوَلُّوا وُجُوهَكُمْ شَطْرَهُ) 2:144; 2:150
- Eh bana ya Israïla, bokila boboto na ngai oyo nasalelaki bino, mpe ete nabotikaki bino likolo ya bikelamoni. (يَا بَنِي إِسْرَائِيلَ اذْكُرُوا نِعْمَتِيَ الَّتِي أَنْعَمْتُ عَلَيْكُمْ وَأَنِّي فَضَّلْتُكُمْ عَلَى الْعَالَمِينَ) 2:47; 2:122
- Ngombe sambo ya mafuta, ya kolia ngombe sambo ya misisa; mpe matomba sambo ya ndambo ya bonene, mpe misusu ya kokauka... (سَبْعَ بَقَرَاتٍ سِمَانٍ يَأْكُلُهُنَّ سَبْعٌ عِجَافٌ وَسَبْعَ سُنبُلَاتٍ خُضْرٍ وَأُخَرَ يَابِسَاتٍ) 12:43; 12:46
- Mpe mpo na yekolo nyonso ezali na tango oyo eyebani. Tango tango na bango ekokoma, ekokosilisa ata ngonga moko te mpe ekokoleya te. (وَلِكُلِّ أُمَّةٍ أَجَلٌ فَإِذَا جَاءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ) 7:34; 10:49
- Maye babomeli yango na kombo mosusu kasi ya Allah te, kasi moto oyo alelaki (ya nzala) kasi azali na mokano te mpe azali koleka ndelo te, bongo... (أُهِلَّ لِغَيْرِ اللَّهِ بِهِ فَمَنِ اضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَإِنَّ) 6:145; 16:115
- Mpe tango babengeli bango: 'Bolanda maye Allah akitisi,' balobaki: 'Te, tokolanda maye tokutaki batata na biso na yango.' (وَإِذَا قِيلَ لَهُمُ اتَّبِعُوا مَا أَنزَلَ اللَّهُ قَالُوا بَلْ نَتَّبِعُ مَا) 2:170; 31:21
- Alobaki: 'Eh bato na ngai, bondima Allah; bozali na nzambe mosusu te kasi ye moko. Boni bozali kobanga te?' (قَالَ يَاقَوْمِ اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 7:65; 23:23
Matching Phrases 10 words

